// presets + Pico palette -> src/css/themes.css (AUTO-GENERATED; do not edit)
import { writeFileSync } from 'node:fs';
import { themes } from './presets.js';
import { picoColors } from './pico-colors.js';

// ported from react-multistyle-ui/src/lib/themes/color.js
function hexToHsl(hex) {
  const m = String(hex).replace('#', '').trim();
  const f = m.length <= 4 ? (i) => parseInt(m[i] + m[i], 16) : (i) => parseInt(m.slice(i * 2, i * 2 + 2), 16);
  const [r, g, b] = [f(0) / 255, f(1) / 255, f(2) / 255];
  const max = Math.max(r, g, b), min = Math.min(r, g, b), l = (max + min) / 2;
  let h = 0, s = 0;
  if (max !== min) {
    const d = max - min;
    s = l > 0.5 ? d / (2 - max - min) : d / (max + min);
    h = (max === r ? (g - b) / d + (g < b ? 6 : 0) : max === g ? (b - r) / d + 2 : (r - g) / d + 4) * 60;
  }
  return { h: Math.round(h), s: Math.round(s * 100), l: Math.round(l * 100) };
}
const invertHex = (hex, lift = 20) => {
  const { h, s, l } = hexToHsl(hex);
  return `hsl(${h}, ${s}%, ${Math.min(100, Math.max(0, 100 - l + lift))}%)`;
};

const LIFT = { text: 20, surface: 10, cardSurface: 14 };
const ld = (light, dark) => `light-dark(${light}, ${dark})`;

let css = '/* AUTO-GENERATED by scripts/gen-themes.js - do not edit. */\n@layer ms.tokens {\n';

// Pico themes (named repo themes override same-named ones: slate keeps repo values)
for (const [n, c] of Object.entries(picoColors)) {
  if (themes[n]) continue;
  css += `.theme-${n}{--ms-primary:${c.primary};--ms-secondary:${c.secondary}}\n`;
}

for (const [n, t] of Object.entries(themes)) {
  const c = t.common;
  const pick = (k) => {
    const dark = t.dark[k] ?? invertHex(t.light[k], LIFT[k]);
    return ld(t.light[k], dark);
  };
  css += `.theme-${n}{--ms-primary:${c.primary};--ms-secondary:${c.secondary};` +
    `--ms-info:${c.info};--ms-success:${c.success};--ms-warning:${c.warning};--ms-error:${c.error};` +
    `--ms-surface:${pick('surface')};--ms-card:${pick('cardSurface')};--ms-text:${pick('text')};` +
    `--ms-radius-btn:${c.buttonRadius};--ms-radius-card:${c.cardRadius};--ms-radius-input:${c.inputRadius};--ms-border-w:${c.borderWidth}}\n`;
}

// custom: user --ms-surface is LIGHT-ONLY; dark uses default dark surface/text. Card derived from surface.
css += `.theme-custom{--ms-c-surface:light-dark(var(--ms-surface,#fff),var(--ms-default-surface-dark));` +
  `--ms-c-text:light-dark(var(--ms-default-text-light),var(--ms-default-text-dark));` +
  `--ms-c-card:color-mix(in oklch,var(--ms-c-surface),var(--ms-c-text) 4%)}\n`;
css += '}\n';
writeFileSync(new URL('../src/css/themes.css', import.meta.url), css);
console.log('themes.css:', css.length, 'bytes');
